function boundaryPlain(text){return String(text).normalize('NFD').replace(/[\u0300\u0301\u0302\u0304\u030c\u0331]/g,'').normalize('NFC').toLowerCase()}
function initializeSpellingBoundaries(data){
 const byId=new Map();for(const rule of SPELLING_BOUNDARY_REVIEWS)for(const id of rule.wordIds){if(!byId.has(id))byId.set(id,[]);byId.get(id).push(rule)}
 for(const w of data.words){
  if(isSouthernWord(w))continue;
  const ids=[w.id,...(w.mergedWordIds||[]),...(w.attestations||[]).map(a=>a.id)];
  const rules=[...new Set(ids.flatMap(id=>byId.get(id)||[]))];
  if(rules.length)w.spellingBoundaries=rules.map(({key,parts,separator,separators,kind})=>({key,parts,separator,...(separators?{separators}:{}),kind,reviewed:true}));
 }
}
function reviewedSpelling(w,text,mode){
 if(!w.spellingBoundaries?.length)return text;
 if(/[~～]/.test(text))return String(text).split(/([~～])/).map(part=>/[~～]/.test(part)?part:reviewedSpelling(w,part,mode)).join('');
 const compact=String(text).replace(/[\s'’\-]/g,'');let units=[];
 if(mode==='ye'){
  let end=0;for(const m of compact.matchAll(/([a-züê]*?[aeiouüê][a-züê]*?)([xfrv])/gi)){
   if(m.index!==end)return text;const chars=Array.from(m[1]);chars[chars.length-1]+=m[2];units.push(...chars.map((value,i)=>({value,key:m[1][i].toLowerCase()})));end=m.index+m[0].length;
  }if(end!==compact.length)return text;
 }else{
  let before='';
  for(const char of String(text).replace(/[\s\-]/g,'').normalize('NFD')){if(char==="'"||char==='’'){before="'";continue}if(/\p{M}/u.test(char)&&units.length)units[units.length-1].value+=char;else {units.push({value:char,key:char.toLowerCase(),before});before=''}}
  units=units.map(u=>({...u,key:boundaryPlain(u.value)}));
 }
 const key=units.map(u=>u.key).join(''),rule=w.spellingBoundaries.find(r=>r.key===key);if(!rule)return text;
 let offset=0;return rule.parts.map((part,index)=>{const result=units.slice(offset,offset+part.length).map((u,i)=>(i?u.before||'':'')+u.value).join('');offset+=part.length;return (index?(rule.separators?.[index-1]??rule.separator):'')+result}).join('').normalize('NFC');
}
